DELIMITER $$
CREATE TRIGGER `after_bainop_insert` AFTER INSERT ON `bainop` FOR EACH ROW BEGIN
  VALUES (NEW.maHS, 'Nộp bài', CONCAT('Học sinh ', NEW.maHS, ' đã nộp bài ', NEW.maTL), 'Info');
