DELIMITER $$
CREATE TRIGGER `after_diemso_delete` AFTER DELETE ON `diemso` FOR EACH ROW BEGIN
  DECLARE idThongBao INT;
  DECLARE tenMon VARCHAR(100);
  DECLARE tenLoai VARCHAR(100);

  -- Lấy tên môn học (để thông báo đẹp hơn)
  SELECT tenMonHoc INTO tenMon
  FROM monhoc
  WHERE maMonHoc = OLD.maMonHoc
  LIMIT 1;

  SET tenLoai = OLD.loaiDiem;

  -- 1) GHI LOG (HS)
  VALUES (
    OLD.maHS,
    'Xóa điểm',
    CONCAT(
      'Điểm ', tenLoai, ' môn ', IFNULL(tenMon, OLD.maMonHoc),
      ' của học sinh ', OLD.maHS, ' đã bị xóa.'
    ),
    'Warning'
  );

  -- 2) GỬI THÔNG BÁO CHO HỌC SINH
  VALUES (
    'Điểm học tập bị xóa',
    CONCAT(
      'Điểm ', tenLoai, ' môn ', IFNULL(tenMon, OLD.maMonHoc),
      ' của bạn đã bị xóa khỏi hệ thống.'
    ),
    NULL,       -- NULL = hệ thống
    NOW(),
    'HocSinh',  -- chỉ học sinh nhận
    OLD.maHS    -- đúng học sinh bị xóa điểm
  );

  SET idThongBao = LAST_INSERT_ID();

  VALUES (OLD.maHS, idThongBao, 'Chưa đọc');

END
$$
DELIMITER ;
