CREATE TRIGGER `after_giaovien_delete` AFTER DELETE ON `giaovien` FOR EACH ROW BEGIN
  DECLARE tenGV VARCHAR(100) DEFAULT '';
  DECLARE idThongBao INT;

  -- Lấy tên giáo viên (phòng trường hợp không tìm thấy)
  SELECT COALESCE(hoVaTen, '') INTO tenGV
  FROM user
  WHERE userID = OLD.maGV
  LIMIT 1;

  -- Ghi lịch sử xóa giáo viên
  VALUES (
      OLD.maGV,
      'Xóa giáo viên',
      CONCAT('Giáo viên ', tenGV,
             ' (mã: ', OLD.maGV,
             ') đã bị xóa khỏi hệ thống.'),
      'Warning'
  );

  -- Tạo thông báo cho Admin
  VALUES (
      'Xóa hồ sơ giáo viên',
      CONCAT('Giáo viên ', tenGV, ' đã bị xóa.'),
      NULL,
      NOW()
  );

  SET idThongBao = LAST_INSERT_ID();

  -- Gửi thông báo tới tất cả Admin
  SELECT userID, idThongBao, 'Chưa đọc'
  FROM user
  WHERE vaiTro = 'Admin';
END
$$
