DELIMITER $$
CREATE TRIGGER `trg_AfterInsert_HocSinh` AFTER INSERT ON `hocsinh` FOR EACH ROW BEGIN
    DECLARE lop_id INT;

    -- Tìm lớp tương ứng với tên lớp trong cột lopHocPhuTrach
    SELECT maLop INTO lop_id
    FROM lophoc
    WHERE tenLop = NEW.lopHocPhuTrach
    LIMIT 1;

    -- Nếu tìm thấy lớp
    IF lop_id IS NOT NULL THEN
        -- Thêm vào bảng hocsinh_lophoc
        VALUES (NEW.maHS, lop_id);

        -- Tự động thêm tất cả môn học của lớp đó vào bảng điểm
        SELECT NEW.maHS, lm.maMonHoc, 'hk1_mieng', NULL
        FROM lophoc_monhoc AS lm
        WHERE lm.maLop = lop_id;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_Update_HocSinhLop` AFTER UPDATE ON `hocsinh` FOR EACH ROW BEGIN
    DECLARE lop_id INT DEFAULT NULL;

    -- Kiểm tra thay đổi lớp (xử lý cả trường hợp NULL)
    IF (OLD.lopHocPhuTrach <> NEW.lopHocPhuTrach
        OR (OLD.lopHocPhuTrach IS NULL AND NEW.lopHocPhuTrach IS NOT NULL)
        OR (OLD.lopHocPhuTrach IS NOT NULL AND NEW.lopHocPhuTrach IS NULL)) THEN
        
        -- Tìm mã lớp tương ứng
        SELECT maLop INTO lop_id
        FROM lophoc
        WHERE tenLop = NEW.lopHocPhuTrach
        LIMIT 1;

        -- Nếu lớp tồn tại
        IF lop_id IS NOT NULL THEN

            -- Cập nhật bảng trung gian lớp – học sinh
            DELETE FROM hocsinh_lophoc WHERE maHS = NEW.maHS;
            VALUES (NEW.maHS, lop_id);

            -- Xoá toàn bộ điểm cũ của học sinh
            DELETE FROM diemso WHERE maHS = NEW.maHS;

            -- Tạo bộ điểm mặc định cho lớp mới
            SELECT NEW.maHS, lm.maMonHoc, 'hk1_mieng', NULL
            FROM lophoc_monhoc lm
            WHERE lm.maLop = lop_id;
        END IF;

    END IF;
END
$$
DELIMITER ;

