CREATE TABLE `thongbao` (
  `maThongBao` int(11) NOT NULL,
  `tieuDe` varchar(255) DEFAULT NULL,
  `noiDung` text DEFAULT NULL,
  `tepDinhKem` varchar(255) DEFAULT NULL,
  `ngayGui` datetime DEFAULT current_timestamp(),
  `nguoiGui` int(11) DEFAULT NULL,
  `userID_nhan` int(11) DEFAULT NULL,
  `vaiTroNhan` enum('TatCa','Admin','GiaoVien','HocSinh') NOT NULL DEFAULT 'TatCa',
  `daXoa` tinyint(1) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `thongbao`
--


--
-- Triggers `thongbao`
--
DELIMITER $$
CREATE TRIGGER `after_thongbao_delete` AFTER DELETE ON `thongbao` FOR EACH ROW BEGIN
  DECLARE senderName VARCHAR(100) DEFAULT '';

  IF OLD.nguoiGui IS NOT NULL THEN
    SELECT hoVaTen INTO senderName FROM user WHERE userID = OLD.nguoiGui;
  END IF;

  -- Ghi log xóa thông báo
  VALUES (
    IFNULL(OLD.nguoiGui, 0),
    'Xóa thông báo',
    CONCAT(
      IF(senderName <> '', CONCAT('Người dùng ', senderName, ' xóa thông báo: '), 'Hệ thống xóa thông báo: '),
      OLD.tieuDe
    ),
    'Warning'
  );

  -- Xóa các dòng liên quan trong bảng thongbaouser
  DELETE FROM thongbaouser WHERE maThongBao = OLD.maThongBao;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_thongbao_insert` AFTER INSERT ON `thongbao` FOR EACH ROW BEGIN
  DECLARE senderName VARCHAR(100) DEFAULT '';
  DECLARE receiverCount INT DEFAULT 0;
  DECLARE tmpAffected INT DEFAULT 0;

  -- Nếu có người gửi, lấy tên người gửi (an toàn nếu không tìm thấy -> NULL -> '')
  IF NEW.nguoiGui IS NOT NULL THEN
    SELECT hoVaTen INTO senderName FROM user WHERE userID = NEW.nguoiGui LIMIT 1;
    SET senderName = COALESCE(senderName, '');
  END IF;

  -- Ghi log hệ thống
  VALUES (
    IFNULL(NEW.nguoiGui, 0),
    'Tạo thông báo',
    CONCAT(
      IF(CHAR_LENGTH(senderName) > 0,
         CONCAT('Người dùng ', senderName, ' tạo thông báo: '),
         'Hệ thống tạo thông báo: '
      ),
      COALESCE(NEW.tieuDe,''), ' - ', COALESCE(NEW.noiDung,'')
    ),
    'Info'
  );

  -- Gửi thông báo cho tất cả Admin
  SELECT userID, NEW.maThongBao FROM user WHERE vaiTro = 'Admin';
  SET receiverCount = ROW_COUNT();

  -- Nếu có người gửi, gửi lại thông báo cho chính họ (tránh sót)
  IF NEW.nguoiGui IS NOT NULL THEN
    SET tmpAffected = ROW_COUNT(); -- 1 nếu chèn thành công, 0 nếu đã tồn tại/ignore
    SET receiverCount = receiverCount + tmpAffected;
  END IF;

  -- Ghi log phụ cho hệ thống
  VALUES (
    IFNULL(NEW.nguoiGui, 0),
    'Gửi thông báo',
    CONCAT('Thông báo "', COALESCE(NEW.tieuDe,''), '" được gửi đến ', receiverCount, ' người dùng.'),
    'Info'
  );
END
$$
DELIMITER ;

